mapper.insert:
INSERT INTO SYSCFG (
    LIB_ID, CONFIG_CODE, CONFIG_NAME, CONFIG_VALUE,
    SYS_RUSR_ID, SYS_RUSR_IP, SYS_RUSR_DTTM, SYS_MUSR_ID, SYS_MUSR_IP, SYS_MUSR_DTTM
) VALUES (
    #{libId}, 'WEEK_START', '주 시작 요일', #{weekStart},
    #{stamp.userId}, #{stamp.ip}, #{stamp.utcNow}, #{stamp.userId}, #{stamp.ip}, #{stamp.utcNow}
)
ON DUPLICATE KEY UPDATE CONFIG_VALUE = VALUES(CONFIG_VALUE), SYS_MUSR_ID = VALUES(SYS_MUSR_ID),
    SYS_MUSR_IP = VALUES(SYS_MUSR_IP),
    SYS_MUSR_DTTM = GREATEST(VALUES(SYS_MUSR_DTTM), DATE_ADD(SYS_MUSR_DTTM, INTERVAL 1 SECOND))

INSERT INTO SYSCFG (
    LIB_ID, CONFIG_CODE, CONFIG_NAME, CONFIG_VALUE,
    SYS_RUSR_ID, SYS_RUSR_IP, SYS_RUSR_DTTM, SYS_MUSR_ID, SYS_MUSR_IP, SYS_MUSR_DTTM
) VALUES (
    #{libId}, 'WEB_MENU_GROUPS_V1', '웹 메뉴 폴더 배치', #{groups},
    #{stamp.userId}, #{stamp.ip}, #{stamp.utcNow}, #{stamp.userId}, #{stamp.ip}, #{stamp.utcNow}
)
ON DUPLICATE KEY UPDATE CONFIG_VALUE = VALUES(CONFIG_VALUE), SYS_MUSR_ID = VALUES(SYS_MUSR_ID),
    SYS_MUSR_IP = VALUES(SYS_MUSR_IP), SYS_MUSR_DTTM = VALUES(SYS_MUSR_DTTM)
